#!/usr/bin/env python3
"""Build the From One to Zero benchmark comparison dashboard from saved reports."""
from __future__ import annotations
import json, math, statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def old_report(path):
    d=json.loads(path.read_text())
    ops=d['operation_summary']
    return {
      'id':'baseline-fast-v2','name':'Existing · fast-v2 / PyTorch','date':d['created_at_utc'],
      'runtime':'PyTorch · CUDA','pipeline':d['pipeline'],'model':d['checkpoint'],
      'startup':d['startup_ms'].get('process_start_to_models_ready'),'photos':d['photos'],
      'runs':d['runs'],'operations':ops,
      'sections':[
        {'label':'Raw photo decode','median_ms':ops.get('preprocessing.decode_and_orient_rgb',{}).get('median_ms',0),'children':[{'label':'Decode and orient RGB photo','median_ms':ops.get('preprocessing.decode_and_orient_rgb',{}).get('median_ms',0)}]},
        {'label':'Coordinate-crop preprocessing','median_ms':ops.get('preprocessing.coordinate_crop_total',{}).get('median_ms',0),'children':[
          {'label':'Segmentation image preparation','median_ms':ops.get('preprocessing.segmentation_image_processor',{}).get('median_ms',0)},
          {'label':'Segmentation model inference','median_ms':ops.get('preprocessing.segmentation_model_forward',{}).get('median_ms',0)},
          {'label':'Extract water class mask','median_ms':ops.get('preprocessing.extract_water_class_mask',{}).get('median_ms',0)},
          {'label':'Mask mapping and lower-water crop','median_ms':sum(ops.get('preprocessing.'+k,{}).get('median_ms',0) for k in ['segmentation_class_map_projection','water_mask_to_crop_grid','select_lower_water_rectangle','resize_source_water_crop','coordinate_mapping_crop_canvas_and_mask_apply_other'])}]},
        {'label':'Final tensor preparation and waviness inference','median_ms':ops.get('waviness_inference.model_input_to_score',{}).get('median_ms',0),'children':[
          {'label':'ToTensor and ImageNet normalization','median_ms':ops.get('preprocessing.to_tensor_and_imagenet_normalization',{}).get('median_ms',0)},
          {'label':'EfficientNet-B0 forward','median_ms':ops.get('waviness_inference.efficientnet_b0_forward',{}).get('median_ms',0)}]}
      ],
      'total':d['latency_summary']['total_raw_to_score_ms'],
      'protocol':d['protocol'],'notes':d.get('notes',[]),
      'source':str(path.relative_to(ROOT))
    }
def current_report(path):
    d=json.loads(path.read_text())
    groups={}
    for r in d['runs']:
      for k,v in r.get('stages_ms',{}).items(): groups.setdefault('pipeline.'+k,[]).append(v)
    ops={}
    for k,vals in groups.items():
      vals=sorted(vals); ops[k]={'count':len(vals),'median_ms':sum(vals)/len(vals) if len(vals)%2 else (vals[len(vals)//2-1]+vals[len(vals)//2])/2,'p95_ms':vals[max(0,math.ceil(.95*len(vals))-1)],'max_ms':vals[-1]}
    return {
      'id':'baseline-fast-v2.1','name':'Current · fast-v2.1 / MIGraphX + ONNX','date':d['created_at_utc'],
      'runtime':'MIGraphX segmentation · ONNX Runtime CPU regressor','pipeline':d['pipeline'],
      'model':d['models']['regressor']['path'],'checkpoint':d['checkpoint_setting'],
      'startup':d['startup_to_ready_ms'],'photos':d['cohort'],'runs':d['runs'],'operations':ops,
      'total':d['latency_summary']['client_raw_to_score_ms'],'server_total':d['latency_summary']['server_pipeline_ms'],
      'sections':[
        {'label':'Raw HEIC decode','median_ms':ops.get('pipeline.decode_ms',{}).get('median_ms',0),'children':[{'label':'Decode and orient raw HEIC','median_ms':ops.get('pipeline.decode_ms',{}).get('median_ms',0)}]},
        {'label':'Step 1 tensor preparation and segmentation','median_ms':ops.get('pipeline.step1_tensor_prep_ms',{}).get('median_ms',0)+ops.get('pipeline.step1_segmentation_ms',{}).get('median_ms',0),'children':[{'label':'Prepare 448 × 448 segmentation tensor','median_ms':ops.get('pipeline.step1_tensor_prep_ms',{}).get('median_ms',0)},{'label':'SegFormer-B0 segmentation inference','median_ms':ops.get('pipeline.step1_segmentation_ms',{}).get('median_ms',0)}]},
        {'label':'Mask projection and lower-water crop','median_ms':sum(ops.get('pipeline.'+k,{}).get('median_ms',0) for k in ['mask_projection_ms','crop_selection_ms','coordinate_map_and_source_crop_ms']),'children':[{'label':'Project predicted mask','median_ms':ops.get('pipeline.mask_projection_ms',{}).get('median_ms',0)},{'label':'Select lower-water rectangle','median_ms':ops.get('pipeline.crop_selection_ms',{}).get('median_ms',0)},{'label':'Map crop and extract source pixels','median_ms':ops.get('pipeline.coordinate_map_and_source_crop_ms',{}).get('median_ms',0)}]},
        {'label':'Final masked image and JPEG','median_ms':ops.get('pipeline.final_canvas_resize_and_mask_ms',{}).get('median_ms',0)+ops.get('pipeline.final_jpeg_roundtrip_ms',{}).get('median_ms',0),'children':[{'label':'Resize canvas and apply water mask','median_ms':ops.get('pipeline.final_canvas_resize_and_mask_ms',{}).get('median_ms',0)},{'label':'Encode and decode final JPEG','median_ms':ops.get('pipeline.final_jpeg_roundtrip_ms',{}).get('median_ms',0)}]},
        {'label':'Regressor tensor preparation and inference','median_ms':ops.get('pipeline.regressor_tensor_prep_ms',{}).get('median_ms',0)+ops.get('pipeline.regressor_inference_ms',{}).get('median_ms',0),'children':[{'label':'Prepare regressor tensor','median_ms':ops.get('pipeline.regressor_tensor_prep_ms',{}).get('median_ms',0)},{'label':'ONNX regressor inference','median_ms':ops.get('pipeline.regressor_inference_ms',{}).get('median_ms',0)}]}
      ],
      'protocol':d['protocol'],'notes':[],'source':str(path.relative_to(ROOT))
    }

def screen_report(path):
    d=json.loads(path.read_text())
    groups={}
    for run in d['runs']:
      for key,value in run.get('stages_ms',{}).items():
        if isinstance(value,(int,float)): groups.setdefault(key,[]).append(value)
    operations={}
    for key,values in groups.items():
      values=sorted(values)
      operations['pipeline.'+key]={'count':len(values),'median_ms':sum(values)/len(values) if len(values)%2 else (values[len(values)//2-1]+values[len(values)//2])/2,
        'p95_ms':values[max(0,math.ceil(.95*len(values))-1)],'max_ms':values[-1]}
    total=d['latency_summary']['server_pipeline_ms']
    def op(key): return operations.get('pipeline.'+key,{}).get('median_ms',0)
    data=json.loads((path.parent/'experiment.json').read_text())
    paired=d.get('paired_screen')
    baseline_path=ROOT/'baseline'/path.name
    if paired is None and data['id']!='baseline-screen' and baseline_path.is_file():
      baseline_data=json.loads(baseline_path.read_text())
      base_by_photo={}
      for run in baseline_data['runs']:
        base_by_photo.setdefault(run['photo'],[]).append(run)
      candidate_by_photo={}
      for run in d['runs']:
        candidate_by_photo.setdefault(run['photo'],[]).append(run)
      per_photo=[]
      for photo,rows in candidate_by_photo.items():
        base_rows=base_by_photo.get(photo,[])
        if not base_rows: continue
        base_score=statistics.median(r['prediction'] for r in base_rows)
        candidate_score=statistics.median(r['prediction'] for r in rows)
        base_crop=base_rows[0].get('crop')
        candidate_crop=rows[0].get('crop')
        per_photo.append({'photo':photo,'base_median_ms':statistics.median(r['server_pipeline_ms'] for r in base_rows),
          'candidate_median_ms':statistics.median(r['server_pipeline_ms'] for r in rows),
          'base_prediction':base_score,'candidate_prediction':candidate_score,
          'prediction_delta':candidate_score-base_score,'crop_changed':base_crop!=candidate_crop,
          'baseline_crop':base_crop,'candidate_crop':candidate_crop})
      paired={'baseline_report':str(baseline_path.relative_to(ROOT)),
        'median_latency_delta_ms':total['median_ms']-baseline_data['latency_summary']['server_pipeline_ms']['median_ms'],
        'median_absolute_prediction_delta':statistics.median(abs(x['prediction_delta']) for x in per_photo) if per_photo else None,
        'photos_with_changed_crop':sum(x['crop_changed'] for x in per_photo),'per_photo':per_photo}
    notes=[]
    if d.get('profile'):
      notes.append(d['profile'].get('note','Profile timings include profiling overhead.'))
    if d.get('variant')=='heic-lowres-roi':
      notes.append('Thumbnail-based segmentation was used only where an embedded thumbnail was available; other photos used the baseline full-frame fallback.')
    if d.get('quality_metrics'):
      notes.append(f"Held-out test quality measured on {d['quality_metrics'].get('count',0)} photos; see report details for MAE, RMSE, bias, and R².")
    else:
      notes.append('Speed screen only. Prediction and crop deltas on this small cohort are diagnostic, not a quality gate.')
    return {'id':data['id'],'name':data['name'],'date':d['created_at_utc'],'runtime':d['runtime'],
      'pipeline':f"{d.get('pipeline_profile','fast-v2.1-coordinate')} · {d['variant']}",'model':d.get('regressor_model') or d['step1_model'],
      'startup':d['startup_to_ready_ms'],'photos':d['cohort'],'runs':d['runs'],'operations':operations,
      'total':total,'server_total':total,'protocol':d['protocol'],'notes':notes,'source':str(path.relative_to(ROOT)),
      'paired_screen':paired,'sections':[
        {'label':'HEIC decode','median_ms':op('decode_ms'),
         'children':([{'label':'Decode embedded thumbnail','median_ms':op('thumbnail_decode_ms')},
                      {'label':'Decode selected source tiles','median_ms':op('source_region_decode_ms')}]
                     if d.get('variant')=='heic-lowres-roi' else
                     [{'label':'Decode and orient raw HEIC','median_ms':op('decode_ms')}])},
        {'label':'Step 1 tensor preparation and segmentation','median_ms':op('step1_tensor_prep_ms')+op('step1_segmentation_ms'),
         'children':[{'label':f"Prepare {d.get('step1_size',448)} × {d.get('step1_size',448)} segmentation tensor",'median_ms':op('step1_tensor_prep_ms')},
                     {'label':'SegFormer-B0 inference','median_ms':op('step1_segmentation_ms')}]},
        {'label':'Mask projection and crop selection','median_ms':op('mask_projection_ms')+op('crop_selection_ms')+op('coordinate_map_and_source_crop_ms'),
         'children':[{'label':'Project water mask','median_ms':op('mask_projection_ms')},
                     {'label':'Select lower-water rectangle','median_ms':op('crop_selection_ms')},
                     {'label':'Map crop coordinates','median_ms':op('coordinate_map_and_source_crop_ms')}]},
        {'label':'Final masked image and regression','median_ms':op('final_canvas_resize_and_mask_ms')+op('final_jpeg_roundtrip_ms')+op('regressor_tensor_prep_ms')+op('regressor_inference_ms'),
         'children':[{'label':'Resize final canvas and apply mask','median_ms':op('final_canvas_resize_and_mask_ms')},
                     {'label':'JPEG roundtrip','median_ms':op('final_jpeg_roundtrip_ms')},
                     {'label':'Prepare regressor tensor','median_ms':op('regressor_tensor_prep_ms')},
                     {'label':'Run waviness regressor','median_ms':op('regressor_inference_ms')}]}
      ],'profile':d.get('profile'),'model_setup':d.get('model_setup'),'step1_sha256':d.get('step1_sha256'),
      'training_summary':d.get('training_summary'),'quality_comparison':d.get('quality_comparison'),
      'speed_comparison':d.get('speed_comparison'),'checkpoint':d.get('checkpoint'),
      'regressor_sha256':d.get('regressor_sha256'),'stage_elapsed_seconds':d.get('stage_elapsed_seconds'),
      'quality_metrics':d.get('quality_metrics') or d.get('quality_comparison',{}).get('test_metrics_by_mode',{}).get('fp16-retrained-regressor'),
      'quality_snapshot':d.get('split_snapshot'),'regressor_model':d.get('regressor_model'),
      'pytorch_checkpoint_env':d.get('pytorch_checkpoint_env'),
      'pytorch_checkpoint_note':d.get('pytorch_checkpoint_note'),
      'checkpoint_training_manifest':d.get('checkpoint_training_manifest'),
      'checkpoint_training_summary':d.get('checkpoint_training_summary')}

def main():
    prior=ROOT/'baseline-fast-v2-existing/baseline-20261102T074824Z.json'
    latest=max((ROOT/'baseline-fast-v2.1').glob('baseline-*.json'))
    experiments=[old_report(prior),current_report(latest)]
    screen_reports=[]
    for folder in sorted(ROOT.iterdir()):
      if not folder.is_dir() or folder.name.startswith('baseline-'):
        continue
      reports=sorted(folder.glob('screen-*.json'))
      if reports:
        screen_reports.append(screen_report(reports[-1]))
    data={'experiments':experiments+screen_reports}
    encoded=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
    page=HTML.replace('__DATA__',encoded)
    (ROOT/'index.html').write_text(page)
    print(f'Wrote {ROOT / "index.html"} from {prior.name} and {latest.name}')

HTML=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>From One to Zero · Benchmark comparisons</title><style>
:root{--ink:#142b38;--muted:#5b7078;--paper:#f4f7f4;--card:#fff;--line:#dce5e1;--navy:#153c4a;--teal:#237b78;--green:#208451;--amber:#b77914;--orange:#c25b19;--red:#bd3f38;--shadow:0 10px 30px rgba(20,43,56,.07)}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}header{background:linear-gradient(120deg,#123642,#1c5960);color:#f8fbf8;padding:32px max(24px,calc((100vw - 1260px)/2))}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:11px;font-weight:800;color:#9fd8c7}h1{font-size:clamp(28px,4vw,40px);line-height:1.1;margin:8px 0}.subtitle{color:#d4e5e0;max-width:900px;margin:0}.meta{font-size:12px;color:#b6d2ce;margin-top:14px}.wrap{max-width:1260px;margin:auto;padding:24px}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 16px}.control{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px;font-weight:750}select{font:inherit;color:var(--ink);background:white;border:1px solid var(--line);border-radius:9px;padding:8px}.spacer{flex:1}.checks{display:flex;gap:10px;flex-wrap:wrap}.check{font-size:12px;color:var(--muted)}.panel,.card{background:var(--card);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow)}.panel{margin:0 0 15px;overflow:hidden}.panel-head{padding:15px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-head h2{font-size:17px;margin:0}.panel-head p{font-size:12px;color:var(--muted);margin:3px 0 0}.panel-body{padding:16px 18px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:15px}.card{padding:15px}.label{font-size:10px;color:var(--muted);font-weight:850;text-transform:uppercase;letter-spacing:.08em}.value{font-size:23px;font-weight:780;margin:6px 0 1px;font-variant-numeric:tabular-nums}.note{font-size:11px;color:var(--muted)}.notice{background:#fff8e9;border:1px solid #efdfb8;padding:11px 14px;border-radius:10px;color:#68501b;margin-bottom:14px;font-size:12px}.row,.table-head{display:grid;grid-template-columns:minmax(230px,340px) minmax(100px,1fr) 90px 90px 90px;gap:12px;align-items:center}.table-head{font-size:10px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:0 7px 7px}.row{padding:8px 7px;border-top:1px solid #edf1ef}.name{font-size:12px;overflow-wrap:anywhere}.rail{height:9px;background:#edf2ef;border-radius:99px;overflow:hidden}.bar{height:100%;border-radius:99px;background:linear-gradient(90deg,#43a98c,#237b78)}.bar.medium{background:linear-gradient(90deg,#e6c15d,#b77914)}.bar.high{background:linear-gradient(90deg,#e88c43,#c25b19)}.bar.hot{background:linear-gradient(90deg,#e2695f,#bd3f38)}.waterfall-rail{position:relative;background:repeating-linear-gradient(90deg,#edf2ef 0,#edf2ef calc(10% - 1px),#dce5e1 calc(10% - 1px),#dce5e1 10%)}.waterfall-segment{position:absolute;top:0;height:100%;min-width:1px;border-radius:3px}.section-total{background:#eaf2ef;cursor:pointer}.waterfall-section{display:block;border:1px solid #dce5e1;border-radius:9px;overflow:hidden;margin:0 0 8px}.waterfall-section>summary{list-style:none;display:grid}.waterfall-section>summary::-webkit-details-marker{display:none}.waterfall-section>summary:hover{background:#dfece7}.disclosure{display:inline-block;width:16px;color:var(--teal);transition:transform .15s ease}.waterfall-section:not([open]) .disclosure{transform:rotate(-90deg)}.child-row{background:#f8faf9}.child-row:nth-child(odd){background:#f0f5f3}.child-row .name{padding-left:20px;color:var(--muted)}.remainder-row{background:#eef0f1}.num{text-align:right;font-size:11px;font-variant-numeric:tabular-nums}.num strong{font-size:12px}.group{margin-bottom:16px}.group:last-child{margin-bottom:0}.group-title{font-size:13px;margin:0 0 8px;color:var(--navy)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:right;padding:9px 8px;border-bottom:1px solid #edf1ef;white-space:nowrap}th{color:var(--muted);font-size:10px;text-transform:uppercase}td:first-child,th:first-child{text-align:left;white-space:normal}.pill{border-radius:999px;background:#edf5f2;padding:4px 9px;font-size:10px;font-weight:800}.footer{font-size:11px;color:var(--muted);padding:4px 2px 20px}details summary{cursor:pointer;font-weight:700}.empty{color:var(--muted);padding:16px}@media(max-width:850px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.row,.table-head{grid-template-columns:minmax(170px,230px) minmax(65px,1fr) 65px 65px 65px;gap:7px}.max{display:none}}@media(max-width:600px){.wrap{padding:15px 10px}.cards{gap:7px}.card{padding:11px}.value{font-size:19px}.panel-head,.panel-body{padding:12px}.row,.table-head{grid-template-columns:minmax(120px,1.4fr) minmax(42px,.8fr) 55px 55px;gap:5px}.name{font-size:10px}.num{font-size:9px}.num strong{font-size:10px}.toolbar{align-items:flex-start}}
</style></head><body><header><div class="eyebrow">Baseline preparation · From One to Zero</div><h1>Prediction benchmark experiments</h1><p class="subtitle">Inspect each saved benchmark or compare them side by side. Section totals waterfall across the whole prediction; component bars waterfall within each section.</p><div class="meta" id="meta"></div></header><main class="wrap"><div class="toolbar"><label class="control">View <select id="mode"><option value="individual">Individual experiment</option><option value="compare">Side-by-side comparison</option></select></label><label class="control" id="experiment-control">Experiment <select id="experiment"></select></label><div class="checks" id="compare-select" hidden></div><div class="spacer"></div><span class="pill">Bars scale within each stage group</span></div><div class="notice">Earlier candidate reports are small-cohort speed screens; their score and crop differences are diagnostic. The FP16 retraining report uses the complete held-out test split and includes quality metrics.</div><div class="notice">These reports are different pipeline implementations: the earlier baseline uses the PyTorch fast-v2 path and v19 checkpoint; the current baseline uses fast-v2.1 MIGraphX segmentation and an ONNX CPU regressor. Treat the side-by-side latency as an implementation comparison, not a controlled model-only comparison.</div><div id="individual"><section class="cards" id="cards"></section><section class="panel" id="model-evaluation" hidden><div class="panel-head"><div><h2>FP16 retraining and held-out evaluation</h2><p>Checkpoint selected on validation MAE; held-out test evaluated after selection.</p></div></div><div class="panel-body" id="evaluation-details"></div></section><section class="panel"><div class="panel-head"><div><h2>Startup and model loading</h2><p>One-time work, excluded from each photo’s raw-to-score latency.</p></div><span class="pill" id="startup"></span></div><div class="panel-body" id="startup-detail"></div></section><section class="panel"><div class="panel-head"><div><h2>Benchmark breakdown</h2><p>Non-overlapping stage shares of total median raw-to-score latency, displayed cumulatively as a waterfall.</p></div></div><div class="panel-body" id="operations"></div></section><section class="panel"><div class="panel-head"><div><h2>Per-photo measured runs</h2><p>Warm-up runs are excluded; every measured result is shown.</p></div></div><div class="panel-body table-wrap"><table><thead><tr><th>Photo</th><th>Run</th><th>Score</th><th>Raw to score</th><th>Server pipeline</th></tr></thead><tbody id="runs"></tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Experiment details</h2></div></div><div class="panel-body"><details><summary>Models, photo cohort, protocol and notes</summary><pre id="details"></pre></details></div></section></div><section class="panel" id="comparison" hidden><div class="panel-head"><div><h2>Side-by-side results</h2><p>Selected saved experiments.</p></div><span class="pill" id="compare-count"></span></div><div class="panel-body"><div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Runtime/model</th><th>Startup</th><th>Photo count</th><th>Test MAE</th><th>Test split</th><th>Median raw to score</th><th>p95</th><th>Min–max</th></tr></thead><tbody id="compare-rows"></tbody></table></div><h3 class="group-title" style="margin-top:22px">Cumulative stage shares · each waterfall reaches the full raw-to-score total</h3><div id="compare-ops"></div></div></section><p class="footer">Parent stage totals overlap their child timings and operation durations do not necessarily sum to total latency. The earlier report’s raw-to-score measurement is model execution; the current report’s client measurement includes local request overhead. Source reports and benchmark runners are retained in their experiment directories.</p></main><script id="data" type="application/json">__DATA__</script><script>
const DATA=JSON.parse(document.getElementById('data').textContent).experiments;const $=id=>document.getElementById(id);const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const ms=x=>x==null?'—':`${Number(x).toFixed(2)} ms`;const sec=x=>x==null?'—':x>=1000?`${(x/1000).toFixed(2)} s`:ms(x);const grade=x=>x>15?'hot':x>5?'high':x>=1?'medium':'low';const mode=$('mode'),experiment=$('experiment');
function init(){experiment.innerHTML=DATA.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');$('compare-select').innerHTML=DATA.map(d=>`<label class="check"><input type="checkbox" value="${esc(d.id)}" checked> ${esc(d.name)}</label>`).join('');}
function selected(){return DATA.find(d=>d.id===experiment.value)}
function allChecked(){return [...document.querySelectorAll('#compare-select input:checked')].map(x=>DATA.find(d=>d.id===x.value)).filter(Boolean)}
function median(x){return x?.median_ms??null}function p95(x){return x?.p95_ms??null}function maxval(x){return x?.max_ms??null}
function renderWaterfall(d,container){const total=d.total?.median_ms||0;let sections=(d.sections||[]).map(x=>({...x,median_ms:Math.max(0,x.median_ms||0)}));let sum=sections.reduce((a,x)=>a+x.median_ms,0);if(sum>total&&sum>0){const factor=total/sum;sections=sections.map(x=>({...x,median_ms:x.median_ms*factor}))}const colors=['#237b78','#208451','#b77914','#c25b19','#5279a8','#7356a8','#84939a'];let cursor=0;let html='<div class="table-head"><span>Section total</span><span>Share of full prediction time</span><span>Total</span><span>Share</span><span>Range</span></div>';for(let i=0;i<sections.length;i++){const section=sections[i],sectionStart=cursor,sectionPct=total?section.median_ms/total*100:0;cursor+=section.median_ms;let group=`<details class="waterfall-section" open><summary class="row section-total"><div class="name"><span class="disclosure" aria-hidden="true">⌄</span><strong>${esc(section.label)}</strong></div><div class="rail waterfall-rail"><div class="waterfall-segment" style="left:${total?sectionStart/total*100:0}%;width:${sectionPct}%;background:${colors[i%colors.length]}"></div></div><div class="num"><strong>${ms(section.median_ms)}</strong></div><div class="num">${sectionPct.toFixed(1)}%</div><div class="num max">${(total?sectionStart/total*100:0).toFixed(1)}–${(total?(sectionStart+section.median_ms)/total*100:0).toFixed(1)}%</div></summary>`;let children=(section.children||[]).map(x=>({...x,median_ms:Math.max(0,x.median_ms||0)}));let childSum=children.reduce((a,x)=>a+x.median_ms,0);if(childSum>section.median_ms&&childSum>0){const factor=section.median_ms/childSum;children=children.map(x=>({...x,median_ms:x.median_ms*factor}));childSum=section.median_ms}children.push({label:'Other within section',median_ms:Math.max(0,section.median_ms-childSum)});let childCursor=0;for(const child of children){const from=section.median_ms?childCursor/section.median_ms*100:0,pct=section.median_ms?child.median_ms/section.median_ms*100:0;childCursor+=child.median_ms;group+=`<div class="row child-row"><div class="name">↳ ${esc(child.label)}</div><div class="rail waterfall-rail"><div class="waterfall-segment" style="left:${from}%;width:${pct}%;background:${colors[i%colors.length]};opacity:.78"></div></div><div class="num">${ms(child.median_ms)}</div><div class="num">${pct.toFixed(1)}%</div><div class="num max">${from.toFixed(1)}–${(from+pct).toFixed(1)}%</div></div>`}html+=group+'</details>'}const remainder=Math.max(0,total-cursor);if(remainder>0){const start=cursor,pct=total?remainder/total*100:0;html+=`<div class="row section-total remainder-row"><div class="name"><strong>Other / request overhead</strong></div><div class="rail waterfall-rail"><div class="waterfall-segment" style="left:${total?start/total*100:0}%;width:${pct}%;background:${colors[sections.length%colors.length]}"></div></div><div class="num"><strong>${ms(remainder)}</strong></div><div class="num">${pct.toFixed(1)}%</div><div class="num max">${(total?start/total*100:0).toFixed(1)}–100.0%</div></div>`}container.innerHTML=html+'<p class="note">Top rows show each section’s contribution to total median raw-to-score time. Indented component bars restart at zero within their section; each component waterfall closes with its section remainder. Parent timings overlap their detailed components.</p>'}
function renderModelEvaluation(d){const training=d.training_summary,quality=d.quality_comparison;const panel=$("model-evaluation");panel.hidden=!(training&&quality);if(panel.hidden)return;const m=training.selected_checkpoint_metrics||{};const train=m.train_deterministic||{},val=m.validation||{};const rows=Object.entries(quality.test_metrics_by_mode||{}).map(([name,x])=>`<tr><td>${esc(name)}</td><td>${x.count}/${x.count+x.failures}</td><td>${Number(x.mae).toFixed(5)}</td><td>${Number(x.rmse).toFixed(5)}</td><td>${Number(x.bias).toFixed(5)}</td><td>${Number(x.r2).toFixed(4)}</td></tr>`).join('');const epochs=(training.epoch_history||[]).map(x=>`<tr><td>${x.epoch+1}</td><td>${Number(x.train_loss??NaN).toFixed(5)}</td><td>${Number(x.train_mae??NaN).toFixed(5)}</td><td>${Number(x.val_loss??NaN).toFixed(5)}</td><td>${Number(x.val_mae??NaN).toFixed(5)}</td><td>${Number(x.val_rmse??NaN).toFixed(5)}</td></tr>`).join('');const speed=Object.entries(d.speed_comparison||{}).map(([name,x])=>`<tr><td>${esc(name)}</td><td>${ms(x.latency_summary?.median_ms)}</td><td>${ms(x.latency_summary?.p95_ms)}</td><td>${sec(x.startup_to_ready_ms)}</td><td>${x.successful_photos}/${x.successful_photos+(x.failures||[]).length}</td></tr>`).join('');$("evaluation-details").innerHTML=`<h3 class="group-title">Selected checkpoint · epoch ${training.best_epoch_zero_based+1} of ${training.epochs_completed}</h3><p>Training duration ${Number(training.training_seconds).toFixed(1)} s · ${training.device} · ${training.train_count} train / ${training.validation_count} validation photos · ${esc(training.architecture)}</p><div class="table-wrap"><table><thead><tr><th>Split</th><th>Count</th><th>MAE</th><th>RMSE</th><th>Smooth L1</th></tr></thead><tbody><tr><td>Train (deterministic evaluation)</td><td>${train.count}</td><td>${Number(train.mae).toFixed(5)}</td><td>${Number(train.rmse).toFixed(5)}</td><td>${Number(train.smooth_l1).toFixed(5)}</td></tr><tr><td>Validation</td><td>${val.count}</td><td>${Number(val.mae).toFixed(5)}</td><td>${Number(val.rmse).toFixed(5)}</td><td>${Number(val.smooth_l1).toFixed(5)}</td></tr></tbody></table></div><h3 class="group-title" style="margin-top:20px">Held-out test quality · ${quality.full_common_test_count} common photos</h3><div class="table-wrap"><table><thead><tr><th>Inference mode</th><th>Photos</th><th>MAE</th><th>RMSE</th><th>Bias</th><th>R²</th></tr></thead><tbody>${rows}</tbody></table></div><p>Retrained FP16 MAE change vs FP32: ${Number(quality.candidate_mae_delta_vs_baseline).toFixed(5)} · vs FP16/current regressor: ${Number(quality.candidate_mae_delta_vs_fp16_current_regressor).toFixed(5)}.</p><details style="margin-top:16px"><summary>Per-photo predictions, errors and crop changes</summary><div class="table-wrap"><table><thead><tr><th>Photo / label</th><th>FP32 prediction / abs error</th><th>FP16 current / abs error</th><th>FP16 retrained / abs error</th><th>Crop changed</th></tr></thead><tbody>${(quality.per_photo||[]).map(x=>`<tr><td>${esc(x.photo)} · ${Number(x.label).toFixed(4)}</td><td>${Number(x.baseline_fp32_prediction).toFixed(4)} / ${Number(x.baseline_fp32_absolute_error).toFixed(4)}</td><td>${Number(x.fp16_current_regressor_prediction).toFixed(4)} / ${Number(x.fp16_current_absolute_error).toFixed(4)}</td><td>${Number(x.fp16_retrained_prediction).toFixed(4)} / ${Number(x.fp16_retrained_absolute_error).toFixed(4)}</td><td>${x.fp32_crop===x.fp16_retrained_crop?"No":"Yes"}</td></tr>`).join("")}</tbody></table></div></details><h3 class="group-title" style="margin-top:20px">Speed on the same held-out photos</h3><div class="table-wrap"><table><thead><tr><th>Inference mode</th><th>Median pipeline</th><th>p95</th><th>Startup</th><th>Photos</th></tr></thead><tbody>${speed}</tbody></table></div><details style="margin-top:16px"><summary>Training metrics by epoch</summary><div class="table-wrap"><table><thead><tr><th>Epoch</th><th>Train loss</th><th>Train MAE</th><th>Validation loss</th><th>Validation MAE</th><th>Validation RMSE</th></tr></thead><tbody>${epochs}</tbody></table></div></details><p class="note">Checkpoint: ${esc(training.best_checkpoint)} · regressor SHA-256: ${esc(d.regressor_sha256)} · test split was not used for training or checkpoint selection.</p>`}
function renderIndividual(){const d=selected();$('individual').hidden=mode.value!=='individual';$('comparison').hidden=mode.value!=='compare';$('experiment-control').hidden=mode.value!=='individual';$('compare-select').hidden=mode.value!=='compare';if(mode.value!=='individual')return;$('meta').textContent=`${d.name} · ${d.date} · ${d.runtime}`;const total=d.total;const cards=[['Median raw to score',ms(median(total)),`p95 ${ms(p95(total))}`],['Successful measured runs',`${d.runs.filter(r=>r.status==='ok').length}/${d.runs.length}`,'recorded runs'],['Startup to ready',sec(d.startup),'excluded from photo latency'],['Runtime',d.runtime,d.model]];if(d.quality_metrics)cards.splice(1,0,['Held-out test MAE',Number(d.quality_metrics.mae).toFixed(5),`${d.quality_metrics.count} test photos`]);$('cards').innerHTML=cards.map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="note">${x[2]}</div></div>`).join('');renderModelEvaluation(d);$('startup').textContent=`${sec(d.startup)} to ready`;$('startup-detail').innerHTML=`<div class="row"><div class="name">Process start through model readiness</div><div class="name">One-time initialization</div><div class="num"><strong>${sec(d.startup)}</strong></div><div class="num">—</div><div class="num max">—</div></div><p class="note">Measured separately from photo latency. See experiment details for any additional initialization timings in the source report.</p>`;renderWaterfall(d,$('operations'));$('runs').innerHTML=d.runs.map(r=>`<tr><td>${esc(r.photo)}</td><td>${r.repeat}</td><td>${r.prediction==null?'—':Number(r.prediction).toFixed(5)}</td><td>${ms(r.total_raw_to_score_ms)}</td><td>${ms(r.server_pipeline_ms)}</td></tr>`).join('');$('details').textContent=JSON.stringify({pipeline:d.pipeline,model:d.model,checkpoint:d.checkpoint,photos:d.photos,protocol:d.protocol,source_report:d.source,paired_screen:d.paired_screen,profile:d.profile,model_setup:d.model_setup,quality_metrics:d.quality_metrics,quality_snapshot:d.quality_snapshot,regressor_model:d.regressor_model,regressor_sha256:d.regressor_sha256,pytorch_checkpoint_env:d.pytorch_checkpoint_env,pytorch_checkpoint_note:d.pytorch_checkpoint_note,checkpoint_training_manifest:d.checkpoint_training_manifest,checkpoint_training_summary:d.checkpoint_training_summary,notes:d.notes},null,2)}
function renderCompare(){if(mode.value!=='compare')return;const ds=allChecked();$('meta').textContent=`${ds.length} selected benchmark experiment(s)`;$('compare-count').textContent=`${ds.length} selected`;$('compare-rows').innerHTML=ds.map(d=>`<tr><td>${esc(d.name)}<br><small>${esc(d.date)}</small></td><td>${esc(d.runtime)}<br><small>${esc(d.model)}</small></td><td>${sec(d.startup)}</td><td>${d.runs.length}</td><td>${d.quality_metrics?.mae==null?'—':Number(d.quality_metrics.mae).toFixed(5)}</td><td>${esc(d.quality_snapshot||'—')}</td><td><strong>${ms(median(d.total))}</strong></td><td>${ms(p95(d.total))}</td><td>${ms(d.total.min_ms)} – ${ms(d.total.max_ms)}</td></tr>`).join('')||'<tr><td colspan="9">Select one or more experiments.</td></tr>';$('compare-ops').innerHTML=ds.map(d=>`<details open><summary>${esc(d.name)} · cumulative waterfall</summary></details>`).join('');[...$('compare-ops').querySelectorAll('details')].forEach((el,i)=>{const box=document.createElement('div');box.className='panel-body';renderWaterfall(ds[i],box);el.appendChild(box)})}
function render(){renderIndividual();renderCompare()}init();mode.addEventListener('change',render);experiment.addEventListener('change',render);$('compare-select').addEventListener('change',render);render();
</script></body></html>'''
if __name__=='__main__': main()
